C527_R = [("if (z.mut && z !== me && z.mode === 'free') { mutStep(z, dt); return; }", "if (z.mut && z !== me && z.mode === 'free') { mutStep(z, dt); if (CHAPTER && z.mut === 'armor') chMoveHit(z, dt); return; }   /* c527: 덩치도 가는 길에 몸에 닿은 바리케이트 · 차 · 문 · 사물을 가면서 친다 (밀기만 하던 것) */"), ('    if (z.knockT > 0) { if (z.bombing) chBombIcon(z); knockStep(z, dt); return; }', '    if (z.knockT > 0) { if (z.bombing) chBombIcon(z); if (CHAPTER && z.atkT > 0) z.atkT -= dt * (z.rage ? 1 + rageK() : 1); knockStep(z, dt); return; }   // c527: 바리케이트를 밀다 튕기는 동안에도 공격 쿨타임은 돈다 (밀기만 하고 못 치던 것)'), ('      { const dg = n + { e: 0, n: 1, h: 2 }[d]; h += `<div class="cd"><div class="k">위험도</div><div class="v" style="font-size:20px;letter-spacing:2px">${[1, 2, 3, 4, 5].map((k) => `<span style="color:${k <= dg ? \'#ff5a5a\' : \'#3d4450\'}">☠</span>`).join(\'\')}</div></div>`; }   // c523: 수치 대신 위험도 해골', '      /* c527: 위험도 칸 뺌 */')]
